assert.equal(new Set(ids).size,ids.length);
assert.equal(new Set(data.relationships.map(r=>r.relationship_id)).size,data.relationships.length);
for (const r of data.relationships) {
 assert.ok(ids.includes(r.from_id) && ids.includes(r.to_id),r.relationship_id);
 assert.ok(r.source_reference && r.review_status);
}
